//! 👁️ A cache read pins its actual original ViewModel until clone handoff and source restoration.
use super::*;
/// 🎟️ The response retains this frame and the same registry through success and cancellation.
pub struct OriginalSurfaceViewCapture{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,registry:Option<usize>,cursor:RetainedFieldCursor<ViewModel>,output:ManuallyDrop<Option<ViewModel>>,retirement:RetainedCloneClose,phase:u8,closing:bool,locked:bool,selection:Option<(usize,usize)>,scan:usize,offset:usize,selected:bool}
impl OriginalSurfaceViewCapture{
 pub fn admit(cx:&mut StepContext<'_>,slot:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=Self::birth_demand();let body=cx.retained_grant().maximum_copy_bytes;let binding=OriginalSourceBinding::borrow(cx);semio_framework_job::admit_original_construction(cx,slot,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{binding,decoder,body,registry:None,cursor:Default::default(),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false,locked:false,selection:None,scan:0,offset:0,selected:false}),step(d).progress()))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn registry(&self,registry:&SurfaceContexts)->Result<(),ValueError>{if self.registry.is_some_and(|original|original!=registry as*const _ as usize){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original cached view registry changed"))}if self.locked&&registry.cached_capture!=Some(self as*const _ as usize){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original cached view capture lost its registry lease"))}Ok(())}
 /// 🪟️ Cache and selected-surface reads share the same exclusive original source loan.
 pub fn advance(&mut self,registry:&mut SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(registry,None,cx)}
 /// 🎯️ The selected binding stays borrowed from its exact source while its typed clone is prepared.
 pub fn advance_surface(&mut self,registry:&mut SurfaceContexts,surface:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(registry,Some(surface),cx)}
 fn advance_selected(&mut self,registry:&mut SurfaceContexts,surface:Option<&str>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.registry(registry)?;if self.closing{return Err(invalid().into())}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original view capture cancelled").into())}let selection=surface.map(|s|(s.as_ptr()as usize,s.len()));if self.phase>0&&self.selection!=selection{return Err(invalid().into())}match self.phase{
  0=>{if registry.cached_capture.is_some(){return Ok(false)}if paid(cx,demand::<Self>())?{self.registry=Some(registry as*const _ as usize);registry.cached_capture=Some(self as*const _ as usize);registry.captured_slot=None;self.selection=selection;self.selected=surface.is_none();self.locked=true;self.phase=1}},
  1=>{if !self.selected{let surface=surface.ok_or_else(invalid)?;if self.scan==registry.slots.len(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"selected surface has no original host context").into())}let candidate=registry.slots[self.scan].as_ref().map(|binding|binding.surface.as_str());let count=candidate.map_or(0,|candidate|if candidate.len()==surface.len(){64.min(surface.len().saturating_sub(self.offset))}else{0});let equal=candidate.is_some_and(|candidate|candidate.len()==surface.len()&&candidate.as_bytes()[self.offset..self.offset+count]==surface.as_bytes()[self.offset..self.offset+count]);let d=RetirementDemand{copy_bytes:count.saturating_mul(2)+size_of::<(usize,usize,bool,Option<usize>)>(),depth:1,..Default::default()};if paid(cx,d)?{if equal{self.offset+=count;if self.offset==surface.len(){registry.captured_slot=Some(self.scan);self.selected=true}}else{self.scan+=1;self.offset=0}}return Ok(false)}let present=if let Some(index)=registry.captured_slot{registry.slots[index].as_ref().and_then(|binding|binding.view_state.as_ref()).is_some()}else{registry.view_state.is_some()};if !present{if paid(cx,demand::<u8>())?{self.phase=4;self.cursor.begin_close();}return Ok(false)}let birth=RetainedCloneSource::<ViewModel>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<ViewModel>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};let g=cx.retained_grant();let target=registry.captured_slot;let view=if let Some(index)=target{&mut registry.slots[index].as_mut().ok_or_else(invalid)?.view_state}else{&mut registry.view_state};if semio_framework_job::admit_original_construction(cx,&mut registry.cached_source,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let original=view.take().ok_or_else(invalid)?;match RetainedCloneSource::admit_owned(original,(),g){Ok(result)=>Ok(result),Err((e,original,()))=>{*view=Some(original);Err(e)}}})?{self.phase=2}},
  2=>{let source=registry.cached_source.as_ref().ok_or_else(invalid)?.borrow();if self.cursor.output_ready(){if paid(cx,demand::<Option<ViewModel>>())?{*self.output=self.cursor.take();self.cursor.begin_close();self.phase=3}}else{let d=self.cursor.advance_demands(source,self.body)?;receive(cx,d,|g|self.cursor.advance(source,self.body,g))?;}},
  3|4=>{if self.close_read(registry,cx)?&&paid(cx,demand::<u8>())?{self.phase=5}},
  5|6=>return Ok(true),_=>return Err(invalid().into())}Ok(self.phase>=5)}
 pub fn take_into(&mut self,output:&mut Option<ViewModel>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||self.phase!=5||output.is_some(){return Err(invalid().into())}if !paid(cx,demand::<Option<ViewModel>>())?{return Ok(false)}*output=self.output.take();self.phase=6;Ok(true)}
 fn close_read(&mut self,registry:&mut SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.registry(registry)?;if !self.cursor.close_started(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original cached view cursor closure was not admitted").into())}if !self.cursor.terminal_is_empty(){let d=self.cursor.close_demands(self.body)?;semio_framework_job::close_original_retained_step(cx,d,|g|self.cursor.close_step(g))?;return Ok(false)}if self.locked{if let Some(source)=registry.cached_source.as_mut(){let d=source.next_take_demand(self.body)?;let g=cx.retained_grant();if !cx.should_yield()&&retained_clone_grant_admits(g,d){match source.take_authority(g)?{RetainedCloneSourceTake::Pending(p)=>{cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)},RetainedCloneSourceTake::Ready(view,p)=>{let destination=if let Some(index)=registry.captured_slot{&mut registry.slots[index].as_mut().ok_or_else(invalid)?.view_state}else{&mut registry.view_state};if destination.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original view handback destination is occupied").into())}*destination=Some(view);registry.cached_source.take();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)}}}return Ok(false)}if paid(cx,demand::<(Option<usize>,Option<usize>,bool)>())?{registry.cached_capture=None;registry.captured_slot=None;self.locked=false}return Ok(false)}Ok(true)}
 pub fn close_step(&mut self,registry:&mut SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.closing{if paid(cx,demand::<bool>())?{self.closing=true;self.cursor.begin_close();}return Ok(false)}if !self.close_read(registry,cx)?{return Ok(false)}if !self.retirement.is_empty(){let selected=self.retirement.select(self.body)?;let d=selected.demands();semio_framework_job::close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}if self.output.is_some(){let d=self.retirement.next_owner_demands::<ViewModel>(true,&None,self.body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.output,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn birth_demand()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..demand::<Self>()}}
 pub fn close_demands(&self,registry:&SurfaceContexts)->Result<RetirementDemand,ValueError>{self.registry(registry)?;if !self.closing{return Ok(demand::<bool>())}if !self.cursor.terminal_is_empty(){return self.cursor.close_demands(self.body)}if self.locked{if let Some(source)=registry.cached_source.as_ref(){return source.next_take_demand(self.body)}return Ok(demand::<(Option<usize>,Option<usize>,bool)>())}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.output.is_some(){return self.retirement.next_owner_demands::<ViewModel>(true,&None,self.body)}Ok(Default::default())}
 pub fn terminal_is_empty(&self)->bool{!self.locked&&self.output.is_none()&&self.cursor.terminal_is_empty()&&self.retirement.is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalSurfaceViewCapture{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original surface view capture requires cache restoration and paid closure")}}
